// Option selection (runtime 0.90.0, `selection-rule.v1.md`): the selection block codec, the v5 field 9 it
// frames, and the `proposal` explanation word. `conformance/selection_rule_v1_vectors.json` is
// seam-runtime's fixture, vendored verbatim (generated by its independent stdlib-only
// `scripts/selection_rule_v1_vectors.py`). This SDK frames the block's digest only: the winner recompute
// (§5 steps 6-9, the `rule_cases` / `sealed_cases` groups) is the Rust verifier's and the Python SDK's, so
// those groups are not exercised here.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { create } from "@bufbuild/protobuf";
import {
  type ExplanationEntryInput,
  type SelectionBlock,
  explanationDigest,
  seamCommitmentDigest,
  selectionBody,
  selectionDigest,
} from "../src/crypto.js";
import { commitmentView } from "../src/client.js";
import { CommitmentSchema, ExplanationKind, VoterVerification } from "../gen/seam/api/v1/seam_pb.js";

const V = JSON.parse(
  readFileSync(new URL("../../conformance/selection_rule_v1_vectors.json", import.meta.url), "utf8"),
);
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const CODEC = V.codec as { block: SelectionBlock; body: string; selection_digest: string; field_9: string };
const VERIFIED = (V.sealed_cases as { name: string; block: SelectionBlock; entries: ExplanationEntryInput[]; action: string }[]).find(
  (c) => c.name === "verified",
)!;
const CASES = V.commitment_digest_v5.cases as {
  name: string;
  commitment: Record<string, any>;
  explanation_digest: string;
  selection_digest: string | null;
  certificate_digest: string | null;
  governing_doc_sha256: string | null;
  commitment_digest: string;
}[];

test("the codec block encodes to the vector body, digest and field 9", () => {
  const body = selectionBody(CODEC.block);
  assert.equal(hex(body), CODEC.body);
  assert.equal(body.length, 422);
  const d = selectionDigest(body);
  assert.equal(hex(d), CODEC.selection_digest);
  assert.equal("01" + "0000000000000020" + hex(d), CODEC.field_9);
});

test("the verified case's seven entries (proposal word included) give the vector's explanation digest", () => {
  const populated = CASES.find((c) => c.name === "populated_selection_governed")!;
  assert.equal(hex(explanationDigest(VERIFIED.entries)), populated.explanation_digest);
  assert.equal(populated.explanation_digest, "40a4e742ffce841dcb2deb0ee6912c590a7268068117dd593bbd11bb4f76e34c");
});

test("every commitment_digest_v5 case, field 9 from the slot and from the block", () => {
  for (const c of CASES) {
    const base = {
      ...c.commitment,
      explanation_digest: c.explanation_digest,
      certificate_digest: c.certificate_digest,
      governing_doc_sha256: c.governing_doc_sha256,
    } as any;
    assert.equal(seamCommitmentDigest({ ...base, selection_digest: c.selection_digest }), c.commitment_digest, c.name);
    if (c.selection_digest !== null) {
      assert.equal(seamCommitmentDigest({ ...base, selection: CODEC.block }), c.commitment_digest, `${c.name} (block)`);
      assert.throws(() => seamCommitmentDigest({ ...base, selection: CODEC.block, selection_digest: c.selection_digest }));
    }
  }
});

test("a block the runtime could not have sealed is refused, never hashed", () => {
  const b = CODEC.block;
  const bad: [string, SelectionBlock][] = [
    ["weights descending", { ...b, weights: [{ participant: "carol", weight: 1 }, { participant: "bob", weight: 2 }] }],
    ["weights duplicate", { ...b, weights: [{ participant: "bob", weight: 1 }, { participant: "bob", weight: 2 }] }],
    ["rules_digest 31 bytes", { ...b, rules_digest: (b.rules_digest as string).slice(2) }],
    ["empty winner", { ...b, winner_proposal_id: "" }],
    ["u32 overflow", { ...b, min_ballots: 2 ** 32 }],
    ["negative weight", { ...b, default_weight: -1 }],
  ];
  for (const [name, blk] of bad) assert.throws(() => selectionBody(blk), name);
  // Ascending is by UTF-8 BYTES: "Z" (0x5a) sorts before "a" (0x61), and "é" (0xc3 0xa9) after "z".
  selectionBody({ ...b, weights: [{ participant: "Z", weight: 1 }, { participant: "a", weight: 1 }, { participant: "é", weight: 1 }] });
});

const KINDS: Record<string, ExplanationKind> = {
  vote: ExplanationKind.VOTE,
  proposal: ExplanationKind.PROPOSAL,
};

function servedProto(withSelection: boolean) {
  const c = CASES.find((x) => x.name === "populated_selection_governed")!.commitment;
  const b = CODEC.block;
  return create(CommitmentSchema, {
    id: c.id,
    action: c.action,
    authority: c.authority,
    authMethod: c.auth_method,
    trustBasis: c.trust_basis,
    committer: c.committer,
    governingDocSha256: Buffer.from(CASES[1].governing_doc_sha256!, "hex"),
    ...(withSelection
      ? {
          selection: {
            rule: b.rule,
            ruleVersion: b.rule_version,
            defaultWeight: b.default_weight,
            weights: b.weights.map((w) => ({ participant: w.participant, weight: w.weight })),
            tie: b.tie,
            abstention: b.abstention,
            minBallots: b.min_ballots,
            policyVersion: b.policy_version,
            rulesDigest: Buffer.from(b.rules_digest as string, "hex"),
            participants: [...b.participants],
            onBehalfOf: [...b.on_behalf_of],
            context: b.context.map((x) => ({ ctxRef: x.ctx_ref, contentHash: x.content_hash })),
            winnerProposalId: b.winner_proposal_id,
          },
        }
      : {}),
    explanation: VERIFIED.entries.map((e) => ({
      kind: KINDS[e.kind],
      participant: e.participant,
      proposalId: e.proposal_id,
      value: e.value,
      reason: e.reason,
      ...(e.voter_verification
        ? {
            voterVerification: {
              method: VoterVerification.POP,
              principal: e.voter_verification.principal,
              contentDigest: Buffer.from(e.voter_verification.content_digest as string, "hex"),
              issuedAtMs: BigInt(e.voter_verification.issued_at_ms),
              expiresAtMs: BigInt(e.voter_verification.expires_at_ms),
              signature: Buffer.from(e.voter_verification.signature as string, "hex"),
              signerCertificate: Buffer.from(e.voter_verification.signer_certificate as string, "hex"),
              tenant: e.voter_verification.tenant,
              namespace: e.voter_verification.namespace,
              sessionId: e.voter_verification.session_id,
              openedAtMillis: BigInt(e.voter_verification.opened_at_millis),
              issuer: e.voter_verification.issuer,
              audience: e.voter_verification.audience,
              acceptedAtMs: BigInt(e.voter_verification.accepted_at_ms),
            },
          }
        : {}),
    })),
  });
}

test("commitmentView frames field 9 from the served selection, with explicit presence", () => {
  const governed = CASES.find((c) => c.name === "populated_selection_governed")!;
  const stripped = CASES.find((c) => c.name === "populated_selection_stripped")!;
  const view = commitmentView(servedProto(true));
  assert.equal(view.explanation![0].kind, "proposal");
  assert.equal(seamCommitmentDigest(view), governed.commitment_digest);
  // Absent selection is "not a selection decision": field 9 = 0x00.
  const plain = commitmentView(servedProto(false));
  assert.equal(plain.selection, null);
  assert.equal(seamCommitmentDigest(plain), stripped.commitment_digest);
  // An edited weight moves the digest (a TCT holder sees it).
  const m = servedProto(true);
  m.selection!.weights[0].weight = 3;
  assert.notEqual(seamCommitmentDigest(commitmentView(m)), governed.commitment_digest);
  // A served block the runtime could not have sealed fails closed.
  m.selection!.winnerProposalId = "";
  assert.throws(() => seamCommitmentDigest(commitmentView(m)));
});
